const j = $input.first().json;

function formatList(arr) {
  if (!arr || arr.length === 0) return '(keine)';
  return arr.map(row => `${row.von} — ${row.betreff || '(kein Betreff)'}`).join('
');
}

function formatQ(arr) {
  if (!arr || arr.length === 0) return '(keine)';
  return arr.map(row => `${row.von} — ${row.betreff || '?'} (Score ${row.spam_score ?? '?'}) ${row.virus_name ? '[VIRUS: '+row.virus_name+']' : ''}`).join('
');
}

const heute = $now.toFormat('dd.MM.yyyy');
const promptText = `Erstelle aus den folgenden E-Mail-Daten eine kompakte taegliche Zusammenfassung auf Deutsch fuer eine Telegram-Nachricht (max. 3000 Zeichen, kein Markdown, klare Absaetze).

Aufbau:
1. Ueberschrift mit Datum ${heute}
2. Wichtige Mails zuerst (Clean/Sonstiges), dann Newsletter
3. Kurze Zaehler-Zeile (z.B. "12 Mails gesamt: 3 sauber, 5 Newsletter, ...")
4. Abschnitt "Quarantaene / Spam" mit der Liste unten (falls leer: "keine Eintraege")

Regulaere Mails (${(j.sonstiges || []).length} Stueck):
${formatList(j.sonstiges)}

Newsletter (${(j.newsletter || []).length} Stueck):
${formatList(j.newsletter)}

Spam/Quarantaene (${(j.quarantaene || []).length + (j.spam || []).length} Eintraege):
${formatQ([...(j.quarantaene || []), ...(j.spam || [])])}`;

return [{ json: { promptText, anzahlMails: j.total } }];

let digest = '';
try { digest = $json.candidates[0].content.parts[0].text; } catch (e) {}
if (!digest) digest = 'Digest konnte nicht erstellt werden — Gemini-Antwort war leer. Bitte Execution in n8n pruefen.';
// Telegram-Limit: 4096 Zeichen
digest = String(digest).slice(0, 4000);
return { json: { digest } };
